import { strict as assert } from "node:assert";
import { test } from "node:test";
import { total } from "./total.mjs";

test("adds shipping to a small cart", () => {
  const result = total([{ price: 10 }, { price: 15 }]);
  assert.equal(result.subtotal, 25);
  assert.equal(result.shipping, 5);
  assert.equal(result.grandTotal, 30);
});

test("ships a large cart free", () => {
  const result = total([{ price: 60 }]);
  assert.equal(result.shipping, 0);
  assert.equal(result.grandTotal, 60);
});

